import{_ as o,r as a,o as i,c as l,e as s,a as r,s as c}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"Localization - October CMS - 3.x","titleTemplate":false,"description":"Learn how to translate messages inside CMS themes.","frontmatter":{"subtitle":"Learn how to translate messages inside CMS themes."},"headers":[{"level":3,"title":"Localization File Structure","slug":"localization-file-structure","link":"#localization-file-structure","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"3.x/cms/themes/localization.md","filePath":"3.x/cms/themes/localization.md"}'),p={name:"3.x/cms/themes/localization.md"};function u(d,e,m,g,h,k){const t=a("pre-heading"),n=a("post-heading");return i(),l("div",null,[s(t),e[0]||(e[0]=r("h1",null,"Localization",-1)),s(n),e[1]||(e[1]=c(`<div class="custom-block aside"><p>View the <a href="./../resources/multisite.html">Multisite article</a> to learn how to set the active language for your website.</p></div><p>Themes can provide localization keys through files placed in the <strong>lang</strong> subdirectory of the theme&#39;s directory. These localization keys are registered automatically and can be used inside the theme contents or as backend form labels similar to <a href="./../../extend/system/localization.html">plugin localization</a>.</p><h3 id="localization-file-structure"><a href="#localization-file-structure" class="header-anchor">#</a> Localization File Structure</h3><p>Below is an example of the theme&#39;s <strong>lang</strong> directory.</p><pre class="dir-container"><code><p>├── themes
|   └── website
|       └── <code>lang</code>  <em>← Localization Directory</em>
|           ├── en.json  <em>← Localization File</em>
|           └── fr.json  <em>← Localization File</em></p>
</code></pre><p>The localization file is a JSON file where strings use the &quot;default&quot; translation of the string as the key. For example, if your application has a French translation, you should create a <code>lang/fr.json</code> file.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;I love programming.&quot;</span><span class="token operator">:</span> <span class="token string">&quot;j&#39;adore programmer&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You are also able to define code-based keys by using the complete language key in the JSON file, for example, <code>theme.options.website_name</code> for the <strong>acme</strong> theme can be used.</p><div class="language-json extra-class"><pre class="language-json"><code><span class="token punctuation">{</span>
    <span class="token property">&quot;theme.options.website_name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Language strings can be accessed in your theme files using the <code>trans</code> Twig filter.</p><div class="custom-block tip"><p>View <a href="./../../markup/filter/trans.html">the markup guide</a> to learn more about translation in Twig.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- j&#39;adore programmer --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>I love programming.<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>

<span class="token comment">&lt;!-- October CMS --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>theme.options.website_name<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>trans <span class="token delimiter punctuation">}}</span></span>
</code></pre></div></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../resources/multisite.html">Multisite</a></li><li><a href="./../../extend/system/localization.html">Plugin Localization</a></li></ul></div>`,13))])}const b=o(p,[["render",u]]);export{_ as __pageData,b as default};
